<section class="card history-card"><div class="tabs" role="tablist" aria-label="Historial del beneficiario"><?php foreach(['servicios'=>'Historial de compras','dotaciones'=>'Dotaciones','extras'=>'Viajes extraordinarios','bloqueos'=>'Bloqueos','auditoria'=>'Bitácora'] as $key=>$label):?><button type="button" role="tab" id="tab-<?= $key ?>" aria-controls="panel-<?= $key ?>" aria-selected="<?= $key==='servicios'?'true':'false' ?>" tabindex="<?= $key==='servicios'?'0':'-1' ?>" data-tab="<?= $key ?>"><?= $label ?> <span><?= count($history[$key]) ?></span></button><?php endforeach;?></div>
<?php foreach(['servicios','dotaciones','extras','bloqueos','auditoria'] as $key):?><div id="panel-<?= $key ?>" role="tabpanel" aria-labelledby="tab-<?= $key ?>" tabindex="0" <?= $key!=='servicios'?'hidden':'' ?>><?php if(!$history[$key]):?><div class="empty compact"><span class="empty-icon"><?= icon('clock') ?></span><h3>Sin movimientos registrados</h3><p><?= $key==='servicios'?'Las compras aparecerán al conectar o importar el historial del sistema de caja y entregas.':'Los movimientos de este expediente aparecerán aquí.' ?></p></div><?php elseif($key==='servicios'):?><div class="table-wrap"><table><thead><tr><th>Recibo</th><th>Fecha</th><th>Viajes</th><th>Importe</th><th>Entrega</th></tr></thead><tbody><?php foreach($history[$key] as $h):?><tr><td><?= e($h['recibo']) ?></td><td><?= e($h['fecha']) ?></td><td><?= e($h['viajes']) ?></td><td><?= money($h['importe']) ?></td><td><?= e($h['estado']) ?></td></tr><?php endforeach;?></tbody></table></div><?php elseif($key==='dotaciones'):?><div class="table-wrap"><table><thead><tr><th>Cuota</th><th>Tarifa</th><th>Estado</th><th>Vigencia / cambio</th><th>Justificación del cambio</th></tr></thead><tbody><?php foreach($history[$key] as $h):?><tr><td><?= e($h['dotacion']) ?> viajes / mes</td><td><?= money($h['tarifa']) ?></td><td><span class="badge <?= $h['status_dotacion']==='1'?'status-1':'status-0' ?>"><?= $h['status_dotacion']==='1'?'Vigente':'Histórica' ?></span></td><td><?= e($h['fecha_baja_dotacion']?:$h['creado_en']) ?></td><td><?= e($h['desc_baja_dotacion']?:'Cuota actual') ?></td></tr><?php endforeach;?></tbody></table></div><?php elseif($key==='extras'):?><div class="table-wrap"><table><thead><tr><th>Autorización</th><th>Viajes</th><th>Autoridad</th><th>Justificación</th><th>Estado</th></tr></thead><tbody><?php foreach($history[$key] as $h):?><tr><td>#<?= e($h['id_venta_extraordinaria']) ?><small class="cell-subtitle"><?= e($h['fecha_autorizacion']) ?></small></td><td><?= e($h['num_dotacion']) ?></td><td><?= e($h['autoridad']) ?></td><td><?= e($h['justificacion_venta']) ?></td><td><?= e(['0'=>'Cancelada','1'=>'Disponible','2'=>'Estado 2 · por homologar','3'=>'Estado 3 · por homologar'][$h['status_venta_extraordinaria']]??'Por homologar') ?></td></tr><?php endforeach;?></tbody></table></div><?php elseif($key==='bloqueos'):?><div class="timeline"><?php foreach($history[$key] as $h):?><article><span class="timeline-dot"></span><div><strong><?= e($h['motivo']) ?> · <?= $h['status_padron_bloqueo']==='1'?'Vigente':'Concluido' ?></strong><p><?= e($h['desc_padron_bloqueado']) ?></p><small><?= e($h['fecha_padron_bloqueado'].' · '.$h['operador']) ?></small><?php if($h['fecha_padron_desbloqueo']):?><p>Reactivación: <?= e($h['fecha_padron_desbloqueo']) ?><br><?= e($h['justificacion_reactivacion']) ?></p><?php endif;?></div></article><?php endforeach;?></div><?php else:?><div class="timeline"><?php foreach($history[$key] as $h):?><article><span class="timeline-dot"></span><div><strong><?= e($h['accion']) ?></strong><p><?= e($h['operador']) ?></p><small><?= e($h['creado_en']) ?></small><details><summary>Ver detalle del movimiento</summary><pre class="audit-detail"><?= e(json_encode(json_decode($h['detalle'],true),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)) ?></pre></details></div></article><?php endforeach;?></div><?php endif;?></div><?php endforeach;?></section>
